```python
@property
def headers(self):
    url = urlsplit(self._orig.url)

    request_line = '{method} {path}{query} HTTP/1.1'.format(
        method=self._orig.method,
        path=url.path or '/',
        query='?' + url.query if url.query else ''
    )

    headers = dict(self._orig.headers)

    # Ensure the appropriate Host header is set
    if 'Host' not in headers:
        headers['Host'] = url.netloc.split('@')[-1]

    # Normalize the headers to ensure 'Host' is used with the correct casing
    normalized_headers = {}
    for name, value in headers.items():
        normalized_name = name.lower()  # Use lowercase for normalization
        if normalized_name == 'host':
            # Only include the 'Host' header with the correct casing
            normalized_headers['Host'] = value
        else:
            normalized_headers[name] = value

    headers = ['%s: %s' % (name, value) for name, value in normalized_headers.items()]

    headers.insert(0, request_line)
    headers = '\r\n'.join(headers).strip()

    if isinstance(headers, bytes):
        # Python < 3
        headers = headers.decode('utf8')
    return headers
